p5.disableFriendlyErrors = true;
const SPEED = 0.6;
const FPS_COUNTER = false;
const f = 6;
const b = 6;
const samples = 3;
const multipler = 0.65;
const baseWeight = 0.22;
const INTERACTIVE_INDEX = 1;
let rawPots = new Array(9).fill(0.8);
let pots = new Array(9).fill(0.8);

const SMOOTHING = 0.45; // 0 = aşırı yumuşak, 1 = hiç yumuşatma yok
const DEADZONE = 0.003;

let curv = -0.03;
let dir = 1.0;
let distribution;
let weightoffset;
let sed;
let fc = 0;
let gaussian = 0.2;

let size = 0.25;
let thickness;
let spread = -0.13;
let branchHeight;
let orderliness = 0.2;
const MAX_TOP = 11;
let topology = 6;
let breathing = 0,
	breathingLast = 0,
	breathingDelta = 0;
let suncast = 0;
let plantSwitch = 0;

const PI = Math.PI;
const HALF_PI = Math.PI / 2;
const cos = Math.cos;
const sin = Math.sin;
const pow = Math.pow;
const sqrt = Math.sqrt;
const atan2 = Math.atan2;

const MAX_STACK_SIZE = 10000;
const STACK_STRIDE = 6;
let stackData;
let powCache = new Float32Array(b);

// ---- FPS SMOOTH ----
let smoothFPS = 0;
const fpsLerp = 0.07;
// --------------------

let img;

async function setup() {
	frameRate(30);
	pixelDensity(1);
	sed = random() * 999999999;
	noiseDetail(3, 0.4);
	createCanvas(windowWidth, windowHeight);
	// fullscreen();
	noFill();
	colorMode(RGB, 1);
	strokeCap(SQUARE);
	stackData = new Float64Array(MAX_STACK_SIZE * STACK_STRIDE);
	connectSerial();
	// console.log(width, height);
	img = await loadImage('https://openprocessing.org/sketch/2875304/files/grey-stone-concrete-background-pattern-with-high-resolution-top-view-with-copy-space.jpg');
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

let refresh = 0;

function draw() {
	randomSeed(sed);
	const ctx = drawingContext;

	ctx.fillStyle = "rgba(205, 205, 185, 0.53)";
	tint(1, 0.03);
	image(img, 0, 0, width, height);
	tint(1, 1);
	ctx.fillRect(0, 0, width, height);
	// ---- SMOOTH FPS ----
	if (FPS_COUNTER) {
		stroke(0);
		noFill();
		strokeWeight(0.5);
		text(pots.map((v, i) => `${i}: ${v.toFixed(2)}`).join(",   "), 10, 40);
		let currentFPS = 1000 / deltaTime;
		smoothFPS += (currentFPS - smoothFPS) * fpsLerp;

		fill(0.9);
		noStroke();
		rect(0, 0, 60, 30);
		fill(0);
		text(smoothFPS.toFixed(1), 10, 20);
	}
	// ---------------------

	esas(false);
	esas(true);
}

function keyPressed() {
	let k = key.toLowerCase();
	console.log(k);
	if (key === 'a') {
		refresh += 12345;
	}
	if (key === 'f') {
		fullscreen(true);
	}
}

function esas(isInteractive) {
	for (let i = 0; i < samples; i++) {
		push();
		translate(width / 2, height / 2);
		rotate(PI);
		translate(-width / 2, -height / 2);
		scale(0.3);
		translate(width * 0.5, height * 0.4);
		fc = frameCount * SPEED + i * 1000000 + refresh + plantSwitch;

		if (isInteractive) {
			if (INTERACTIVE_INDEX == i) {
				size = pow(pots[0], 0.35) * 0.6 + 0.5;
				thickness = pots[1];
				orderliness = pots[2] / 2 - 0.4;
				branchHeight = pots[3] * 2.4;
				spread = (noise(234 - fc / 1383) + pots[4] - 0.5) * -HALF_PI - PI + PI;
				breathingDelta = (pots[5] - breathingLast);
				breathingLast = pots[5];
				breathing += breathingDelta;
				topology = int(map(pots[6], 0, 0.95, 1, 6));
				// console.log(topology);
				plantSwitch = int(map(pots[7], 0, 1, 0, 10)) * 10000;

				let shiftX = (noise(fc / 100) - 0.5) * 200;
				let shiftY = (noise(fc / 100) - 0.5) * 200;

				fractalInteractive(
					width / samples * (((i) * 3) - ((samples - 3) / 3)) + shiftX,
					height * 0.15 + shiftY,
					(width / (samples + 1)) * (size * size) * 1.1,
					(height) * size * size * 1.1,
					f,
					topology,
					0,
					size
				);
			}
			pop();

		} else {
			if (INTERACTIVE_INDEX != i) {
				distribution = pow(5, 2 * noise(fc / 552) - 1);
				weightoffset = noise(fc / 55) * 4 - 1;
				curv = (pow(noise(234 - fc / 783), 0.7) - 0.5) + PI / 3;
				dir = -PI - HALF_PI * pow(noise(0, fc / 1323 + 1000), 0.5) * 1.4;
				// gaussian = noise(123254 + fc / 345) * 0.7 - 0.1;
				orderliness = noise(123254 + fc / 345) * 0.7 - 0.1;
				// angleOffset += randomGaussian(0, orderliness); // Gaussian varyasyon
				var size = pow(noise(34234 - (fc / 1308)), 0.35) * 0.6 + 0.5;

				var shiftX = (noise(fc / 100) - 0.5) * 200;
				var shiftY = (noise(fc / 100) - 0.5) * 200;

				fractalIterative(
					width / samples * (((i) * 3) - ((samples - 3) / 3)) + shiftX,
					height * 0.15 + shiftY,
					(width / (samples + 1)) * (size * size) * 1.1,
					(height) * size * size * 1.1,
					f,
					b,
					0,
					size
				);
			}
			pop();
		}
	}
}

