let port = null;
let reader = null;
let buffer = "";
let isConnecting = false;
let isConnected = false;

async function connectSerial() {
	if (isConnecting || isConnected) return;  // zaten bağlıysa tekrar deneme
	isConnecting = true;

	try {
		const ports = await navigator.serial.getPorts();
		port = ports.length > 0 ? ports[0] : await navigator.serial.requestPort();

		await port.open({ baudRate: 9600 });

		isConnected = true;   // <-- BAĞLANDI
		console.log("Serial connected");
		readLoop();

	} catch (err) {
		console.log("Connect failed, retrying...");
		setTimeout(connectSerial, 2000);
	}

	isConnecting = false;
}

async function readLoop() {
	try {
		reader = port.readable.getReader();

		while (true) {
			const { value, done } = await reader.read();
			if (done) break;

			buffer += new TextDecoder().decode(value);
			let lines = buffer.split("\n");
			buffer = lines.pop();

			if (lines.length > 0) {
				parseLine(lines[lines.length - 1]);
			}
		}
	} catch (err) {
		console.log("Read error");
	}

	cleanupAndReconnect();
}

function parseLine(line) {
	let parts = line.trim().split(",");
	if (parts.length === 9) {
		for (let i = 0; i < 9; i++) {
			let raw = int(parts[i]) / 1023;

			if (Math.abs(raw - pots[i]) > DEADZONE) {
				pots[i] += (raw - pots[i]) * SMOOTHING;
			}

			rawPots[i] = pots[i];
		}
	}
}
async function cleanupAndReconnect() {
	isConnected = false;   // <-- BAĞLANTI KOPTU

	try { if (reader) reader.releaseLock(); } catch {}
	try { if (port) await port.close(); } catch {}

	console.log("Disconnected. Reconnecting...");
	setTimeout(connectSerial, 2000);
}

navigator.serial.addEventListener("disconnect", () => {
	console.log("Device unplugged");
	cleanupAndReconnect();
});


// === Tab: iter ===
function fractalIterative(startX, startY, startLx, startLy, startLayer, branch, startMutation, size) {
	let sp = 0; 

	stackData[sp++] = startX;
	stackData[sp++] = startY;
	stackData[sp++] = startLx;
	stackData[sp++] = startLy;
	stackData[sp++] = startLayer;
	stackData[sp++] = startMutation;

	var ctx = drawingContext;

	for (let i = 0; i < branch; i++) {
		powCache[i] = pow((i + 1) / branch, distribution);
	}

	const g = baseWeight;
	const widthPlusHeightDiv1000 = (width + height) / 1150;

	while (sp > 0) {

		let mutation = stackData[--sp];
		let layer = stackData[--sp];
		let ly = stackData[--sp];
		let lx = stackData[--sp];
		let y = stackData[--sp];
		let x = stackData[--sp];

		let mut = noise(mutation, fc / 253)*0.5 + 0.1;
		let lenMag = sqrt(lx * lx + ly * ly) * size * mut;
		let x2 = x + lx;
		let y2 = y + ly;

		let alpha = (baseWeight * layer) / f + baseWeight;
		let noiseComp = noise(mutation); 
		let sw = widthPlusHeightDiv1000 * ((layer + weightoffset) + noiseComp);

		if (sw > 0.1) {
			ctx.lineWidth = sw * 0.7 * mut * 2;
			ctx.strokeStyle = `rgba(0, ${Math.floor(g*255)}, 0, ${alpha})`;
			ctx.beginPath();
			ctx.moveTo(x, y);
			ctx.lineTo(x2, y2);
			ctx.stroke();
		}

		if (layer > 1) {
			let noiseVal = 1;
			let currentAngle = atan2(ly, lx);

			for (let i = branch - 1; i >= 0; i--) {

				let t = powCache[i];
				let newX = x + lx * t;
				let newY = y + ly * t;
				let newLenMag = lenMag * (multipler + noiseVal);

				let angleOffset = (i * PI + HALF_PI);
				angleOffset += (((((i+1)%2)*2)-1) * (curv - dir));
				// angleOffset += (random() - 0.5 + random() - 0.5) * gaussian; 
				angleOffset += randomGaussian(0, orderliness); // Gaussian varyasyon

				let totalAngle = currentAngle + angleOffset;
				let newLx = cos(totalAngle) * newLenMag;
				let newLy = sin(totalAngle) * newLenMag;
				let newMutation = mutation + random() * 2000;

				stackData[sp++] = newX;
				stackData[sp++] = newY;
				stackData[sp++] = newLx;
				stackData[sp++] = newLy;
				stackData[sp++] = layer - 1;
				stackData[sp++] = newMutation;
			}
		}
	}
}


